// 求图G中顶点度的最大值的函数  
int maxVertexDegree (MGraph G) {  
//用于记录最大的顶点度  
int maxDegree = 0;  
for (int i = 0; i < G.vexnum; i++) {  
//用于记录当前顶点的度  
int degree = 0;  
//遍历当前顶点所在行的所有元素  
for (int j = 0; j < G.vexnum; j++) {  
//如果邻接矩阵中当前元素为1，说明有边，顶点度加：  
if (G.arcs[i][j] == 1) {  
degree++;  
}  
}  
// 更新最大顶点度  
if (degree > maxDegree) {  
maxDegree = degree;  
}  
}  
// 返回最大顶点度  
return maxDegree;
